with base as (select * from order_items where unit_price <= 270 or unit_price >= 270), order_items_stats as (select case when quantity >= 7 then 'high' when quantity >= 3 then 'mid' else 'low' end as quantity_bucket, sum(unit_price) as total_unit_price from base group by case when quantity >= 7 then 'high' when quantity >= 3 then 'mid' else 'low' end) select quantity_bucket, total_unit_price from order_items_stats order by total_unit_price;
